import{_ as e}from"./chunks/erp-feature.lrM-qWjE.js";import{_ as r,o,c as t,a2 as i}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E7%AE%A1%E7%90%86%E5%90%8E%E5%8F%B0.png",p="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",d="/newx-doc/img/ad/zsxq_erp.png",n="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E9%87%87%E8%B4%AD%E8%A1%A8.png",c="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E9%94%80%E5%94%AE%E8%A1%A8.png",h="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E5%BA%93%E5%AD%98%E8%A1%A8.png",u="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E4%BA%A7%E5%93%81%E8%A1%A8.png",s="/newx-doc/img/ERP%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E8%B4%A2%E5%8A%A1%E8%A1%A8.png",q=JSON.parse('{"title":"ERP 演示","description":"","frontmatter":{},"headers":[],"relativePath":"erp-preview.md","filePath":"erp-preview.md","lastUpdated":null}'),E={name:"erp-preview.md"};function _(m,a,A,P,b,g){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="erp-演示" tabindex="-1">ERP 演示 <a class="header-anchor" href="#erp-演示" aria-label="Permalink to &quot;ERP 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><h3 id="_1-1-erp-管理后台" tabindex="-1">1.1 ERP 管理后台 <a class="header-anchor" href="#_1-1-erp-管理后台" aria-label="Permalink to &quot;1.1 ERP 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：“ERP 系统”下的「采购管理」「销售管理」「库存管理」「产品管理」「财务管理」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>erp</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p><img src="'+l+'" alt="管理后台"></p><h3 id="_1-2-erp-后端" tabindex="-1">1.2 ERP 后端 <a class="header-anchor" href="#_1-2-erp-后端" aria-label="Permalink to &quot;1.2 ERP 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-erp</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-erp</code> 服务</li></ul><h3 id="_1-3-erp-移动端" tabindex="-1">1.3 ERP 移动端 <a class="header-anchor" href="#_1-3-erp-移动端" aria-label="Permalink to &quot;1.3 ERP 移动端&quot;">​</a></h3><p>ERP 提供 uni-app 移动端，采购、销售、库存、产品和财务都可以在手机上处理，详见 <a href="./erp/mobile">《移动端 ERP》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-erp</code> 目录</li></ul><p><img src="'+p+'" alt="移动端"></p><h2 id="_2-erp-启动" tabindex="-1">2. ERP 启动 <a class="header-anchor" href="#_2-erp-启动" aria-label="Permalink to &quot;2. ERP 启动&quot;">​</a></h2><p>参见 <a href="./erp/build">《ERP 手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-erp-交流" tabindex="-1">3. ERP 交流 <a class="header-anchor" href="#_3-erp-交流" aria-label="Permalink to &quot;3. ERP 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+d+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要分为 5 个核心模块：采购、销售、库存、产品、财务。</p><p><img src="'+e+'" alt="ERP 功能列表"></p><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>ERP 一共有 <strong>30+</strong> 张表，具备一定的业务复杂度，对提升技术能力会有不错的帮助，平时做项目也可以参考参考。</p><h3 id="_5-1-采购管理" tabindex="-1">5.1 采购管理 <a class="header-anchor" href="#_5-1-采购管理" aria-label="Permalink to &quot;5.1 采购管理&quot;">​</a></h3><p>以 <code>erp_purchase_</code> 作为前缀的表，表结构如下：</p><p><img src="'+n+'" alt="采购表"></p><ul><li><a href="./erp/purchase">《【采购】采购订单、入库、退货》</a></li></ul><h3 id="_5-2-销售管理" tabindex="-1">5.2 销售管理 <a class="header-anchor" href="#_5-2-销售管理" aria-label="Permalink to &quot;5.2 销售管理&quot;">​</a></h3><p>以 <code>erp_sale_</code> 作为前缀的表，表结构如下：</p><p><img src="'+c+'" alt="销售表"></p><ul><li><a href="./erp/sale">《【销售】销售订单、出库、退货》</a></li></ul><h3 id="_5-3-库存管理" tabindex="-1">5.3 库存管理 <a class="header-anchor" href="#_5-3-库存管理" aria-label="Permalink to &quot;5.3 库存管理&quot;">​</a></h3><p>以 <code>erp_stock_</code> 作为前缀的表，表结构如下：</p><p><img src="'+h+'" alt="库存表"></p><ul><li><a href="./erp/stock">《【库存】产品库存、库存明细》</a></li><li><a href="./erp/stock-in-out">《【库存】其它入库、其它出库》</a></li><li><a href="./erp/stock-move-check">《【库存】库存调拨、库存盘点》</a></li></ul><h3 id="_5-4-产品管理" tabindex="-1">5.4 产品管理 <a class="header-anchor" href="#_5-4-产品管理" aria-label="Permalink to &quot;5.4 产品管理&quot;">​</a></h3><p>以 <code>erp_product_</code> 作为前缀的表，表结构如下：</p><p><img src="'+u+'" alt="产品表"></p><ul><li><a href="./erp/product">《【产品】产品信息、分类、单位》</a></li></ul><h3 id="_5-5-财务管理" tabindex="-1">5.5 财务管理 <a class="header-anchor" href="#_5-5-财务管理" aria-label="Permalink to &quot;5.5 财务管理&quot;">​</a></h3><p>以 <code>erp_finance_</code> 作为前缀的表，表结构如下：</p><p><img src="'+s+'" alt="财务表"></p><ul><li>《【财务】采购付款、销售收款》</li></ul>',42)])])}const R=r(E,[["render",_]]);export{q as __pageData,R as default};
